import numpy as np


def min_max_dist_dim2_16() -> np.ndarray:
    """Return the deterministic 4-by-4 integer square lattice in row-major order."""
    return np.array(
        [(i, j) for i in range(4) for j in range(4)],
        dtype=float,
    )


